S=$0;read Q;read T;read K||K=0;python3 -c 'import sys,json as j,os,zlib,base64 as B,re;q,T,k,s=sys.argv[1:];t=max(1,int(T));k="".join(c for c in k if c.isalnum())or"0";p=os.path;J=lambda x:j.dumps(x,separators=(",",":"));w=re.findall(r"\w+",q.lower())or["light"];qn=" ".join(w);y=(q+k+str(p.getsize(s)if p.exists(s)else 0)).encode();g=sum((b+1)*257**i for i,b in enumerate(y));u=[1+((g>>i)%997)/10 for i in(0,9,18)];z=[[-2*(i+1)for i in range(3)],u];c=[[110+int(u[j]*((g>>(6*(i+j)))&63))%420 for j in range(3)]for i in range(3)];d=min(t,10);n=(2<<d)-1;Y=[(g+sum(c[i%3])+i*i)%997 for i in range(n)];tz=sum(y%2<1 for y in Y);nz=n-tz;o=list(min((y,i)for i,y in enumerate(Y)));F=c[o[1]%3];tt="Anselm %s V%s"%(" ".join(x.title()for x in w[:8]),k);wv=tt+".wav";os.system("ffmpeg -y -loglevel error -f lavfi -i sine=frequency=%s:duration=%s -f lavfi -i sine=frequency=%s:duration=%s -f lavfi -i sine=frequency=%s:duration=%s -filter_complex \"[0:a][1:a][2:a]amix=3:normalize=0,volume=.28,afade=t=in:d=1,afade=t=out:st=%s:d=2\" %r"%(F[0],t,F[1],t,F[2],t,max(1,t-2),wv));ab=open(wv,"rb").read()if p.exists(wv)else b"";bf=tt+".rmz85";en=B.b85encode(ab);open(bf,"wb").write(en);db=B.b85decode(en);open(wv,"wb").write(db);fc=int(db==ab and len(ab)>0 and p.getsize(wv)==len(ab));G="C NL Z P M F E X L V H".split();nl={"N":qn,"T":w,"M":"STGZC","A":"FCD","G":"B257"};C=[[G[0],qn],[G[1],nl],[G[2],z],[G[3],o],[G[4],"select"],[G[5],len(ab),zlib.crc32(ab)&0xffffffff],[G[6],bf],[G[7],wv],[G[8],tt],[G[9]],[G[10]]];con=int(tz+nz==n);comp=int([x[0]for x in C]==G);pf=int(o==list(min((y,i)for i,y in enumerate(Y))));v=int(j.loads(J(C))==C and con and comp and pf and fc);D={"P":"RMZANS2K","TM":"AUDIO-B257/FINITE-WAV/SELF-ZERO/4","SPACE":"FINITE-WAV","ENUM":"bounded","NLTM":nl,"G":str(g),"Z":z,"CAND":c,"CODE":C,"K":k,"ALL":n,"TZ":tz,"NZ":nz,"CON":con,"COMP":comp,"OPT":o,"OPTCERT":pf,"ENCODED":bf,"WAV":wv,"FILECERT":fc,"TITLE":tt,"MODE":"select","V":v,"ANSCERT":v,"PCC":v,"ZE":v};open(tt+".clcert","w").write(J(D)+"\n"